{"file_path":"src/lexer.js","content":"/**
 * The tokenizer. `scan` turns UTF-8 source text (already decoded to a JS
 * string) into a flat array of tokens, or throws a `LexError` at the first
 * position the grammar rejects.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isIdentStart(ch) {
  return ch !== undefined && /[A-Za-z_]/.test(ch)
}

function isIdentPart(ch) {
  return ch !== undefined && /[A-Za-z0-9_]/.test(ch)
}

function isDecimal(ch) {
  return ch !== undefined && /[0-9]/.test(ch)
}

function isHex(ch) {
  return ch !== undefined && /[0-9a-fA-F]/.test(ch)
}

function isBin(ch) {
  return ch === '0' || ch === '1'
}

function isOct(ch) {
  return ch !== undefined && /[0-7]/.test(ch)
}

class Lexer {
  constructor(text) {
    this.chars = Array.from(text)
    this.len = this.chars.length
    this.i = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  atEnd() {
    return this.i >= this.len
  }

  advance() {
    const ch = this.chars[this.i]
    this.i++
    if (ch === '\n') {
      this.line++
      this.col = 1
    } else if (ch === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return ch
  }
}

function err(pos, reason) {
  return new LexError(pos.line, pos.col, reason)
}

function skipWhitespaceAndComments(lex) {
  for (;;) {
    const ch = lex.peek()
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      lex.advance()
      continue
    }
    if (ch === '/' && lex.peek(1) === '/') {
      while (!lex.atEnd() && lex.peek() !== '\n') lex.advance()
      continue
    }
    if (ch === '/' && lex.peek(1) === '*') {
      const start = lex.pos()
      lex.advance()
      lex.advance()
      let depth = 1
      while (depth > 0) {
        if (lex.atEnd()) throw err(start, 'unterminated block comment')
        if (lex.peek() === '/' && lex.peek(1) === '*') {
          lex.advance()
          lex.advance()
          depth++
        } else if (lex.peek() === '*' && lex.peek(1) === '/') {
          lex.advance()
          lex.advance()
          depth--
        } else {
          lex.advance()
        }
      }
      continue
    }
    break
  }
}

function consumeDigitRun(lex, testFn, hadPrevDigit) {
  let s = ''
  let prev = hadPrevDigit
  for (;;) {
    if (testFn(lex.peek())) {
      s += lex.advance()
      prev = true
      continue
    }
    if (prev && lex.peek() === '_' && testFn(lex.peek(1))) {
      s += lex.advance()
      s += lex.advance()
      prev = true
      continue
    }
    break
  }
  return s
}

function consumeTrailingIdentRun(lex) {
  let s = ''
  while (isIdentPart(lex.peek())) s += lex.advance()
  return s
}

function scanIdent(lex, start) {
  let text = lex.advance()
  text += consumeTrailingIdentRun(lex)
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { pos: start, kind, text }
}

function scanNumber(lex, start) {
  let text = lex.advance()

  if (text === '0' && /[xXbBoO]/.test(lex.peek() ?? '')) {
    const p = lex.advance()
    text += p
    const digitTest = p === 'x' || p === 'X' ? isHex : p === 'b' || p === 'B' ? isBin : isOct
    const digits = consumeDigitRun(lex, digitTest, false)
    text += digits
    if (digits === '') {
      text += consumeTrailingIdentRun(lex)
      throw err(start, `invalid number ${text}`)
    }
  } else {
    text += consumeDigitRun(lex, isDecimal, true)
    if (lex.peek() === '.' && isDecimal(lex.peek(1))) {
      text += lex.advance()
      text += consumeDigitRun(lex, isDecimal, false)
    }
    if (lex.peek() === 'e' || lex.peek() === 'E') {
      if (isDecimal(lex.peek(1))) {
        text += lex.advance()
        text += consumeDigitRun(lex, isDecimal, false)
      } else if ((lex.peek(1) === '+' || lex.peek(1) === '-') && isDecimal(lex.peek(2))) {
        text += lex.advance()
        text += lex.advance()
        text += consumeDigitRun(lex, isDecimal, false)
      }
    }
  }

  if (isIdentPart(lex.peek())) {
    text += consumeTrailingIdentRun(lex)
    throw err(start, `invalid number ${text}`)
  }

  return { pos: start, kind: 'number', text }
}

function readHexDigits(lex, backslashPos, escChar, count) {
  let s = ''
  for (let k = 0; k < count; k++) {
    if (lex.atEnd()) throw err(backslashPos, 'unterminated string', true)
    if (!isHex(lex.peek())) throw err(backslashPos, `invalid escape \\${escChar}`)
    s += lex.advance()
  }
  return s
}

function scanEscape(lex, opening) {
  const backslashPos = lex.pos()
  lex.advance() // backslash
  if (lex.atEnd()) throw err(opening, 'unterminated string')
  const esc = lex.peek()
  switch (esc) {
    case 'n':
      lex.advance()
      return '\n'
    case 't':
      lex.advance()
      return '\t'
    case 'r':
      lex.advance()
      return '\r'
    case '\\':
      lex.advance()
      return '\\'
    case '"':
      lex.advance()
      return '"'
    case '0':
      lex.advance()
      return '\0'
    case 'x': {
      lex.advance()
      const hex = readHexDigitsForX(lex, backslashPos, opening)
      return String.fromCodePoint(parseInt(hex, 16))
    }
    case 'u': {
      lex.advance()
      const cp = readUnicodeEscape(lex, backslashPos, opening)
      return String.fromCodePoint(cp)
    }
    default:
      throw err(backslashPos, `invalid escape \\${esc}`)
  }
}

function readHexDigitsForX(lex, backslashPos, opening) {
  let s = ''
  for (let k = 0; k < 2; k++) {
    if (lex.atEnd()) throw err(opening, 'unterminated string')
    if (!isHex(lex.peek())) throw err(backslashPos, 'invalid escape \\x')
    s += lex.advance()
  }
  return s
}

function readUnicodeEscape(lex, backslashPos, opening) {
  if (lex.atEnd()) throw err(opening, 'unterminated string')
  if (lex.peek() !== '{') throw err(backslashPos, 'invalid escape \\u')
  lex.advance()
  let hex = ''
  for (;;) {
    if (lex.atEnd()) throw err(opening, 'unterminated string')
    if (lex.peek() === '}') break
    if (!isHex(lex.peek())) throw err(backslashPos, 'invalid escape \\u')
    hex += lex.advance()
  }
  lex.advance() // closing }
  if (hex.length === 0) throw err(backslashPos, 'invalid escape \\u')
  const cp = parseInt(hex, 16)
  if (cp > 0x10ffff) throw err(backslashPos, 'invalid escape \\u')
  return cp
}

function scanString(lex, start) {
  lex.advance() // opening quote
  let value = ''
  for (;;) {
    if (lex.atEnd()) throw err(start, 'unterminated string')
    const ch = lex.peek()
    if (ch === '"') {
      lex.advance()
      break
    }
    if (ch === '\n') throw err(lex.pos(), 'newline in string')
    if (ch === '\\') {
      value += scanEscape(lex, start)
      continue
    }
    value += lex.advance()
  }
  return { pos: start, kind: 'string', text: JSON.stringify(value), value }
}

function scanRawString(lex, start) {
  lex.advance() // r
  lex.advance() // opening quote
  let value = ''
  for (;;) {
    if (lex.atEnd()) throw err(start, 'unterminated string')
    const ch = lex.peek()
    if (ch === '"') {
      lex.advance()
      break
    }
    value += lex.advance()
  }
  return { pos: start, kind: 'rawstring', text: JSON.stringify(value), value }
}

function scanPunct(lex, start) {
  const two = (lex.peek() ?? '') + (lex.peek(1) ?? '')
  if (PUNCT2.includes(two)) {
    lex.advance()
    lex.advance()
    return { pos: start, kind: 'punct', text: two }
  }
  const one = lex.peek()
  if (PUNCT1.has(one)) {
    lex.advance()
    return { pos: start, kind: 'punct', text: one }
  }
  throw err(start, `unexpected character ${one}`)
}

export function scan(text) {
  const lex = new Lexer(text)
  const tokens = []
  for (;;) {
    skipWhitespaceAndComments(lex)
    if (lex.atEnd()) break
    const start = lex.pos()
    const ch = lex.peek()
    if (isIdentStart(ch)) {
      tokens.push(scanIdent(lex, start))
    } else if (isDecimal(ch)) {
      tokens.push(scanNumber(lex, start))
    } else if (ch === '"') {
      tokens.push(scanString(lex, start))
    } else if (ch === 'r' && lex.peek(1) === '"') {
      tokens.push(scanRawString(lex, start))
    } else {
      tokens.push(scanPunct(lex, start))
    }
  }
  return tokens
}
