  const lex = new Lexer(text)
  const tokens = []
  for (;;) {
    skipWhitespaceAndComments(lex)
    if (lex.atEnd()) break
    const start = lex.pos()
    const ch = lex.peek()
    if (isIdentStart(ch)) {
      tokens.push(scanIdent(lex, start))
    } else if (isDecimal(ch)) {
      tokens.push(scanNumber(lex, start))
    } else if (ch === '"') {
      tokens.push(scanString(lex, start))
    } else if (ch === 'r' && lex.peek(1) === '"') {
      tokens.push(scanRawString(lex, start))
    } else {
      tokens.push(scanPunct(lex, start))
    }
  }
  return tokens
}
